import re
from decimal import Decimal

_GRAMS_PER = {"g": Decimal(1), "kg": Decimal(1000), "lb": Decimal("453.59237"), "oz": Decimal("28.349523125")}
_WEIGHT_RE = re.compile(r"^(\d+(?:\.\d+)?)([a-zA-Z]+)$")


def parse_weight(text: str) -> int:
    """Parse a weight like "123", "1.5 kg" or " 2 LB " into whole grams, rounded.
    Raises ValueError for missing/unknown units, negative values, or anything malformed."""
    if not isinstance(text, str):
        raise ValueError(f"weight must be a string, got {type(text).__name__}")
    match = _WEIGHT_RE.match(text.strip())
    if not match:
        raise ValueError(f"invalid weight: {text!r}")
    amount, unit = match.groups()
    factor = _GRAMS_PER.get(unit.lower())
    if factor is None:
        raise ValueError(f"unknown unit in weight: {text!r}")
    grams = Decimal(amount) * factor
    # Decimal's default context is ROUND_HALF_EVEN, which matches round().
    return int(grams.to_integral_value())
